# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM DÜŞÜNCESİNDE DİN VE BİLİMİN TAMAMLAYICI BÜTÜNLÜĞÜ</text>\n  <rect x="25" y="50" width="215" height="190" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="132" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">BİLİM (Kevnî Ayetler)</text>\n  <text x="38" y="100" font-size="10.5" fill="#334155">• Konu: Fiziksel evren ve olgular</text>\n  <text x="38" y="122" font-size="10.5" fill="#334155">• Yöntem: Gözlem, deney ve akıl</text>\n  <text x="38" y="144" font-size="10.5" fill="#334155">• Soru: \'Nasıl oluşur ve işler?\'</text>\n  <text x="38" y="166" font-size="10.5" font-weight="bold" fill="#1d4ed8">• İşlev: Sünnetullahı (doğa</text>\n  <text x="46" y="182" font-size="10.5" font-weight="bold" fill="#1d4ed8">yasalarını) keşfederek</text>\n  <text x="46" y="198" font-size="10.5" font-weight="bold" fill="#1d4ed8">insan hayatını kolaylaştırır.</text>\n\n  <rect x="255" y="50" width="190" height="190" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">ORTAK HAKİKAT</text>\n  <rect x="270" y="92" width="160" height="130" rx="8" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="350" y="116" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b45309">Tevhid ve Hikmet</text>\n  <text x="350" y="138" text-anchor="middle" font-size="10.5" fill="#334155">Vahiy ve kâinat aynı</text>\n  <text x="350" y="154" text-anchor="middle" font-size="10.5" fill="#334155">Yaratıcı\'nın eseridir.</text>\n  <text x="350" y="178" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">Akıl + Gözlem + Ahlak</text>\n  <text x="350" y="196" text-anchor="middle" font-size="10" fill="#475569">Marifetullah\'a (Allah\'ı</text>\n  <text x="350" y="210" text-anchor="middle" font-size="10" fill="#475569">tanımaya) ulaştırır.</text>\n\n  <rect x="460" y="50" width="215" height="190" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="567" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">DİN (Vahyî Ayetler)</text>\n  <text x="473" y="100" font-size="10.5" fill="#334155">• Konu: Varlığın gayesi ve ahlak</text>\n  <text x="473" y="122" font-size="10.5" fill="#334155">• Kaynak: İlahi vahiy ve sünnet</text>\n  <text x="473" y="144" font-size="10.5" fill="#334155">• Soru: \'Niçin yaratıldı, amaç ne?\'</text>\n  <text x="473" y="166" font-size="10.5" font-weight="bold" fill="#15803d">• İşlev: Bilimsel güce ahlaki</text>\n  <text x="481" y="182" font-size="10.5" font-weight="bold" fill="#15803d">sorumluluk, hikmet ve</text>\n  <text x="481" y="198" font-size="10.5" font-weight="bold" fill="#15803d">merhamet yönü kazandırır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM MEDENİYETİNDE EĞİTİM VE BİLİM KURUMLARI</text>\n  <rect x="20" y="50" width="210" height="190" rx="8" fill="#ede9fe" stroke="#7c3aed" stroke-width="1.8"/>\n  <text x="125" y="74" text-anchor="middle" font-size="12" font-weight="bold" fill="#5b21b6">1. Akademi ve Yükseköğretim</text>\n  <text x="30" y="98" font-size="10.5" font-weight="bold" fill="#6d28d9">• Suffe (Medine):</text>\n  <text x="38" y="114" font-size="10" fill="#334155">İslam\'ın ilk eğitim kurumu.</text>\n  <text x="30" y="136" font-size="10.5" font-weight="bold" fill="#6d28d9">• Beytülhikme (Bağdat):</text>\n  <text x="38" y="152" font-size="10" fill="#334155">Tercüme ve bilimler akademisi.</text>\n  <text x="30" y="174" font-size="10.5" font-weight="bold" fill="#6d28d9">• Medrese:</text>\n  <text x="38" y="190" font-size="10" fill="#334155">Dinî ve aklî ilimlerin birlikte</text>\n  <text x="38" y="204" font-size="10" fill="#334155">okutulduğu yükseköğretim kurumu.</text>\n\n  <rect x="245" y="50" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="350" y="74" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">2. İhtisas Mektepleri</text>\n  <text x="255" y="98" font-size="10.5" font-weight="bold" fill="#b45309">• Dârülkurrâ:</text>\n  <text x="263" y="114" font-size="10" fill="#334155">Kur\'an-ı Kerim okuma, tecvit,</text>\n  <text x="263" y="128" font-size="10" fill="#334155">hafızlık ve kıraat ihtisas okulu.</text>\n  <text x="255" y="154" font-size="10.5" font-weight="bold" fill="#b45309">• Dârülhadis:</text>\n  <text x="263" y="170" font-size="10" fill="#334155">Hz. Peygamber\'in hadislerinin</text>\n  <text x="263" y="184" font-size="10" fill="#334155">rivayet ve dirayet yönüyle</text>\n  <text x="263" y="198" font-size="10" fill="#334155">incelendiği uzmanlık medresesi.</text>\n\n  <rect x="470" y="50" width="210" height="190" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.8"/>\n  <text x="575" y="74" text-anchor="middle" font-size="12" font-weight="bold" fill="#0369a1">3. Gözlem ve Uygulamalı Tıp</text>\n  <text x="480" y="98" font-size="10.5" font-weight="bold" fill="#075985">• Rasathane (Gözlemevi):</text>\n  <text x="488" y="114" font-size="10" fill="#334155">Astronomi ve yıldız gözlemleri</text>\n  <text x="488" y="128" font-size="10" fill="#334155">(Merâga, Semerkant, İstanbul).</text>\n  <text x="480" y="154" font-size="10.5" font-weight="bold" fill="#075985">• Darüşşifa / Bîmâristan:</text>\n  <text x="488" y="170" font-size="10" fill="#334155">Uygulamalı tıp eğitimi verilen</text>\n  <text x="488" y="184" font-size="10" fill="#334155">ve hastaların tedavi edildiği</text>\n  <text x="488" y="198" font-size="10" fill="#334155">hastane ve tıp merkezleri.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İSLAM MEDENİYETİNDE ÖNCÜ BİLİM İNSANLARI VE ESERLERİ</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Matematik ve Astronomi</text>\n  <text x="30" y="96" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Hârizmî:</text>\n  <text x="38" y="112" font-size="10" fill="#334155">Cebir kurucusu, sıfır (0) ve</text>\n  <text x="38" y="126" font-size="10" fill="#334155">Algoritma (Hisâbü\'l-Cebr).</text>\n  <text x="30" y="148" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Bîrûnî ve Battânî:</text>\n  <text x="38" y="164" font-size="10" fill="#334155">Arzın ölçümü ve trigonometri.</text>\n  <text x="30" y="186" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Uluğ Bey ve Ali Kuşçu:</text>\n  <text x="38" y="202" font-size="10" fill="#334155">Semerkant Rasathanesi, Zîc-i</text>\n  <text x="38" y="216" font-size="10" fill="#334155">Uluğ Bey, er-Risâletü\'l-Fethiyye.</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Tıp, Optik ve Sibernetik</text>\n  <text x="255" y="96" font-size="10.5" font-weight="bold" fill="#166534">• İbn Sînâ (Avicenna):</text>\n  <text x="263" y="112" font-size="10" fill="#334155">el-Kânûn fi\'t-Tıb (Tıp Kanunu).</text>\n  <text x="255" y="134" font-size="10.5" font-weight="bold" fill="#166534">• İbnü\'l-Heysem:</text>\n  <text x="263" y="150" font-size="10" fill="#334155">Kitâbü\'l-Menâzır (Optik bilimi).</text>\n  <text x="255" y="172" font-size="10.5" font-weight="bold" fill="#166534">• el-Cezerî:</text>\n  <text x="263" y="188" font-size="10" fill="#334155">Sibernetik, otomat ve mekanik.</text>\n  <text x="255" y="210" font-size="10.5" font-weight="bold" fill="#166534">• Akşemseddin ve İbnü\'n-Nefîs:</text>\n  <text x="263" y="226" font-size="10" fill="#334155">Mikrop kuramı ve küçük dolaşım.</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Kimya, Coğrafya, Sosyoloji</text>\n  <text x="480" y="96" font-size="10.5" font-weight="bold" fill="#b45309">• Câbir b. Hayyân:</text>\n  <text x="488" y="112" font-size="10" fill="#334155">Deneysel kimya ve imbik.</text>\n  <text x="480" y="138" font-size="10.5" font-weight="bold" fill="#b45309">• Pîrî Reis ve Kâtip Çelebi:</text>\n  <text x="488" y="154" font-size="10" fill="#334155">Kitâb-ı Bahriye, Dünya Haritası</text>\n  <text x="488" y="168" font-size="10" fill="#334155">ve Cihannümâ (Coğrafya).</text>\n  <text x="480" y="194" font-size="10.5" font-weight="bold" fill="#b45309">• İbn Haldûn:</text>\n  <text x="488" y="210" font-size="10" fill="#334155">Mukaddime (Sosyoloji / Umran).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
